def int_eval(expr: str) -> int:
    if not expr or not expr.strip():
        raise ValueError("Empty input")

    # Tokenizer
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c == ' ':
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            num_str = expr[i:j]
            if len(num_str) > 1 and num_str[0] == '0':
                raise ValueError("Leading zero not allowed")
            tokens.append(('NUM', int(num_str)))
            i = j
        elif c == '/':
            if i + 1 < n and expr[i+1] == '/':
                tokens.append(('OP', '//'))
                i += 2
            else:
                raise ValueError("Lone '/' is an error")
        elif c == '*':
            if i + 1 < n and expr[i+1] == '*':
                tokens.append(('OP', '**'))
                i += 2
            else:
                tokens.append(('OP', '*'))
                i += 1
        elif c in '+-()%':
            tokens.append(('OP', c))
            i += 1
        else:
            raise ValueError(f"Invalid character: {c}")

    # Check for two adjacent numbers
    for k in range(len(tokens) - 1):
        if tokens[k][0] == 'NUM' and tokens[k+1][0] == 'NUM':
            raise ValueError("Two adjacent numbers")

    idx = 0
    total = len(tokens)

    def peek():
        return tokens[idx] if idx < total else None

    def consume():
        nonlocal idx
        tok = tokens[idx]
        idx += 1
        return tok

    # AST Node classes
    class NumNode:
        def __init__(self, val): self.val = val
    class BinOpNode:
        def __init__(self, left, op, right): self.left = left; self.op = op; self.right = right
    class UnOpNode:
        def __init__(self, op, operand): self.op = op; self.operand = operand
    class ParensNode:
        def __init__(self, expr): self.expr = expr

    def parse_primary():
        nonlocal idx
        tok = peek()
        if tok is None:
            raise ValueError("Missing operand")
        if tok[0] == 'NUM':
            consume()
            return NumNode(tok[1])
        if tok[0] == 'OP' and tok[1] == '(':
            consume()
            val = parse_expr()
            if idx >= total or tokens[idx][0] != 'OP' or tokens[idx][1] != ')':
                raise ValueError("Unbalanced parentheses")
            consume()
            return ParensNode(val)
        raise ValueError("Syntax error: unexpected token")

    def parse_unary():
        nonlocal idx
        ops = []
        while peek() and peek()[0] == 'OP' and peek()[1] in ('+', '-'):
            ops.append(consume()[1])
        if not ops:
            return parse_factor()
        val = parse_factor()
        for op in reversed(ops):
            val = UnOpNode(op, val)
        return val

    def parse_factor():
        nonlocal idx
        left = parse_primary()
        tok = peek()
        if tok and tok[0] == 'OP' and tok[1] == '**':
            consume()
            # ** is right-associative, so right operand is a unary expression
            # But wait, ** binds tighter than unary on left, but takes unary on right?
            # Prompt: "taking a unary expression as its right operand"
            # Actually, standard parsing: right side of ** is an expression.
            # But precedence of ** > unary.
            # So right side should be parsed as something that respects ** > unary.
            # If we parse unary, we get higher precedence unary.
            # But ** is higher than unary.
            # So right operand of ** should be parsed at a level higher than unary?
            # Wait, if ** is higher precedence, it binds tighter.
            # So in `2**-3`, `**` binds `2` and `-3`.
            # `-3` is a unary expression.
            # So right operand is a unary expression.
            # But wait, if we parse `parse_unary()`, it handles unary ops.
            # But `**` is higher than unary.
            # So `**` should bind before unary?
            # No, `**` is an operator. It binds operands.
            # The right operand is an expression.
            # If `**` is higher precedence than unary, it means `**` binds its operands tightly.
            # But unary `-` is a prefix operator.
            # It binds to what follows.
            # If `**` is higher, it means `**` has priority.
            # But `-` is prefix.
            # Actually, the right operand of `**` is parsed as a `factor`?
            # No, `factor` handles `**`.
            # Let's look at the grammar again.
            # factor : primary { ** unary }  <-- No, ** is right associative.
            # factor : primary { ** factor } ?
            # If ** is right associative, 2**-3**2 is 2**(-3**2).
            # So right operand of first ** is -3**2.
            # -3**2 is unary - applied to 3**2.
            # 3**2 is factor.
            # So right operand of ** is a unary expression?
            # Yes.
            # But wait, if ** is higher precedence than unary, why does it take a unary expression?
            # Because unary is a prefix operator on the right side.
            # It's like `2 ** - 3`.
            # The `-` is part of the right operand.
            # So yes, parse_unary() is correct for right operand.
            # Wait, but if ** is higher precedence, shouldn't it bind `3` directly?
            # No, `-` is an operator.
            # It's always there.
            # The only ambiguity is `-2**2`.
            # Left side of ** is `2`.
            # `-` is to the left of `2`.
            # If ** > unary, ** binds `2` before `-` binds `2`.
            # So `2` is consumed by **.
            # Then `-` binds the result.
            # So left operand of ** is a primary (or factor without **).
            # Right operand of ** is a unary expression?
            # Yes.
            right = parse_unary()
            return BinOpNode(left, '**', right)
        return left

    def parse_term():
        nonlocal idx
        left = parse_unary()
        while peek() and peek()[0] == 'OP' and peek()[1] in ('*', '//', '%'):
            op = consume()[1]
            right = parse_unary()
            left = BinOpNode(left, op, right)
        return left

    def parse_expr():
        nonlocal idx
        left = parse_term()
        while peek() and peek()[0] == 'OP' and peek()[1] in ('+', '-'):
            op = consume()[1]
            right = parse_term()
            left = BinOpNode(left, op, right)
        return left

    def evaluate(node):
        if isinstance(node, NumNode):
            return node.val
        if isinstance(node, BinOpNode):
            left_val = evaluate(node.left)
            right_val = evaluate(node.right)
            if node.op == '+':
                return left_val + right_val
            if node.op == '-':
                return left_val - right_val
            if node.op == '*':
                return left_val * right_val
            if node.op == '//':
                if right_val == 0:
                    raise ZeroDivisionError("integer division or modulo by zero")
                return divmod(left_val, right_val)[0]
            if node.op == '%':
                if right_val == 0:
                    raise ZeroDivisionError("integer division or modulo by zero")
                return divmod(left_val, right_val)[1]
            if node.op == '**':
                if right_val < 0:
                    raise ValueError("Negative exponent not allowed")
                return left_val ** right_val
        if isinstance(node, UnOpNode):
            val = evaluate(node.operand)
            if node.op == '-':
                return -val
            if node.op == '+':
                return val
        if isinstance(node, ParensNode):
            return evaluate(node.expr)
        raise ValueError("Unknown node type")

    result_node = parse_expr()
    if idx < total:
        raise ValueError("Unexpected token at end of expression")
    return evaluate(result_node)

def ipv6_canonical(addr: str) -> str:
    # Reject invalid characters upfront
    if any(c in addr for c in ' %[]/\t\n\r'):
        raise ValueError("Invalid IPv6 address")

    has_double_colon = '::' in addr
    if has_double_colon:
        if addr.count('::') > 1:
            raise ValueError("Invalid IPv6 address")
        parts = addr.split('::')
        if len(parts) != 2:
            raise ValueError("Invalid IPv6 address")

        left = parts[0].split(':') if parts[0] else []
        right = parts[1].split(':') if parts[1] else []

        if any(g == '' for g in left + right):
            raise ValueError("Invalid IPv6 address")
        if len(left) + len(right) > 7:
            raise ValueError("Invalid IPv6 address")

        # Determine how many zero groups are needed.
        # Note: An IPv4 suffix counts as 1 written group here, but will expand to 2 later.
        missing = 8 - len(left) - len(right)
        groups = left + ['0'] * missing + right
    else:
        groups = addr.split(':')
        if len(groups) != 8:
            raise ValueError("Invalid IPv6 address")
        if any(g == '' for g in groups):
            raise ValueError("Invalid IPv6 address")

    # Handle IPv4-mapped or IPv4-compatible suffix
    ipv4_idx = -1
    for i, g in enumerate(groups):
        if '.' in g:
            if i != len(groups) - 1:
                raise ValueError("IPv4 part must be at the end")
            ipv4_idx = i
            break

    if ipv4_idx != -1:
        ipv4_str = groups[ipv4_idx]
        parts = ipv4_str.split('.')
        if len(parts) != 4:
            raise ValueError("Invalid IPv4 part")

        ipv4_vals = []
        for p in parts:
            if not p.isdigit():
                raise ValueError("Invalid IPv4 part")
            if len(p) > 1 and p[0] == '0':
                raise ValueError("Leading zeros in IPv4 part")
            val = int(p)
            if val > 255:
                raise ValueError("Invalid IPv4 octet")
            ipv4_vals.append(val)

        # Replace IPv4 group with two 16-bit hex groups
        g1 = (ipv4_vals[0] << 8) | ipv4_vals[1]
        g2 = (ipv4_vals[2] << 8) | ipv4_vals[3]
        groups[ipv4_idx] = f"{g1:x}"
        groups.insert(ipv4_idx + 1, f"{g2:x}")

    # Now groups must have exactly 8 elements
    if len(groups) != 8:
        raise ValueError("Invalid IPv6 address")

    # Validate and convert hex groups
    hex_chars = set('0123456789abcdefABCDEF')
    final_groups = []
    for g in groups:
        if not g or len(g) > 4:
            raise ValueError("Invalid group length")
        if not all(c in hex_chars for c in g):
            raise ValueError("Invalid hex character")
        final_groups.append(int(g, 16))

    # Check for IPv4-mapped exception (first 80 bits 0, next 16 bits ffff)
    if all(g == 0 for g in final_groups[:6]) and final_groups[6] == 0xffff:
        h, l = final_groups[6], final_groups[7]
        return f"::ffff:{h>>8}.{h&0xff}.{l>>8}.{l&0xff}"

    # Find longest run of consecutive zero groups (length >= 2)
    best_start = -1
    best_len = 0
    curr_start = -1
    curr_len = 0

    for i, g in enumerate(final_groups):
        if g == 0:
            if curr_len == 0:
                curr_start = i
            curr_len += 1
        else:
            if curr_len > best_len:
                best_start = curr_start
                best_len = curr_len
            curr_len = 0
    if curr_len > best_len:
        best_start = curr_start
        best_len = curr_len

    # Format canonical output
    if best_len < 2:
        return ":".join(f"{g:x}" for g in final_groups)

    left_part = final_groups[:best_start]
    right_part = final_groups[best_start + best_len:]
    left_str = ":".join(f"{g:x}" for g in left_part)
    right_str = ":".join(f"{g:x}" for g in right_part)

    if left_str and right_str:
        return f"{left_str}::{right_str}"
    elif left_str:
        return f"{left_str}::"
    elif right_str:
        return f"::{right_str}"
    else:
        return "::"

def ipv6_canonical(addr: str) -> str:
    # Reject invalid characters upfront
    if any(c in addr for c in ' %[]/\t\n\r'):
        raise ValueError("Invalid IPv6 address")

    has_double_colon = '::' in addr
    if has_double_colon:
        if addr.count('::') > 1:
            raise ValueError("Invalid IPv6 address")
        parts = addr.split('::')
        if len(parts) != 2:
            raise ValueError("Invalid IPv6 address")

        left_str, right_str = parts
        left = left_str.split(':') if left_str else []
        right = right_str.split(':') if right_str else []

        if any(g == '' for g in left + right):
            raise ValueError("Invalid IPv6 address")
    else:
        groups_str = addr.split(':')
        # If last group has '.', it counts as 2 groups, so total written should be 7
        if '.' in groups_str[-1]:
            if len(groups_str) != 7:
                raise ValueError("Invalid IPv6 address")
        else:
            if len(groups_str) != 8:
                raise ValueError("Invalid IPv6 address")
        if any(g == '' for g in groups_str):
            raise ValueError("Invalid IPv6 address")
        left = []
        right = groups_str

    # Check for IPv4 suffix
    ipv4_idx_in_right = -1
    if right and '.' in right[-1]:
        ipv4_idx_in_right = len(right) - 1

        ipv4_str = right[-1]
        octets = ipv4_str.split('.')
        if len(octets) != 4:
            raise ValueError("Invalid IPv4 part")

        ipv4_vals = []
        for o in octets:
            if not o.isdigit():
                raise ValueError("Invalid IPv4 part")
            if len(o) > 1 and o[0] == '0':
                raise ValueError("Leading zeros in IPv4 part")
            val = int(o)
            if val > 255:
                raise ValueError("Invalid IPv4 octet")
            ipv4_vals.append(val)

        # Replace last element with two hex groups
        g1 = (ipv4_vals[0] << 8) | ipv4_vals[1]
        g2 = (ipv4_vals[2] << 8) | ipv4_vals[3]
        right[-1] = f"{g1:x}"
        right.append(f"{g2:x}")

    # Count total written groups
    total_written = len(left) + len(right)
    if total_written > 8:
        raise ValueError("Invalid IPv6 address")

    # If :: is used, it must expand to at least one zero group
    if has_double_colon and total_written > 7:
        raise ValueError("Invalid IPv6 address")

    zeros_needed = 8 - total_written
    if zeros_needed < 0:
        raise ValueError("Invalid IPv6 address")

    groups = left + ['0'] * zeros_needed + right

    # Validate and convert hex groups
    final_groups = []
    for g in groups:
        if not g or len(g) > 4:
            raise ValueError("Invalid group length")
        for c in g:
            if c not in '0123456789abcdefABCDEF':
                raise ValueError("Invalid hex character")
        final_groups.append(int(g, 16))

    # IPv4-mapped exception
    if all(g == 0 for g in final_groups[:6]) and final_groups[6] == 0xffff:
        h, l = final_groups[6], final_groups[7]
        return f"::ffff:{h>>8}.{h&0xff}.{l>>8}.{l&0xff}"

    # Find longest run of consecutive zero groups (length >= 2)
    best_start = -1
    best_len = 0
    curr_start = -1
    curr_len = 0

    for i, g in enumerate(final_groups):
        if g == 0:
            if curr_len == 0:
                curr_start = i
            curr_len += 1
        else:
            if curr_len > best_len:
                best_start = curr_start
                best_len = curr_len
            curr_len = 0
    if curr_len > best_len:
        best_start = curr_start
        best_len = curr_len

    if best_len < 2:
        return ":".join(f"{g:x}" for g in final_groups)

    left_part = final_groups[:best_start]
    right_part = final_groups[best_start + best_len:]
    left_str = ":".join(f"{g:x}" for g in left_part)
    right_str = ":".join(f"{g:x}" for g in right_part)

    if left_str and right_str:
        return f"{left_str}::{right_str}"
    elif left_str:
        return f"{left_str}::"
    elif right_str:
        return f"::{right_str}"
    else:
        return "::"

def shell_split(s: str) -> list[str]:
    words = []
    current_parts = []
    word_has_quotes = False
    in_single = False
    in_double = False
    i = 0
    n = len(s)

    while i < n:
        c = s[i]
        if in_single:
            if c == "'":
                in_single = False
            else:
                current_parts.append(c)
        elif in_double:
            if c == '"':
                in_double = False
            elif c == '\\':
                if i + 1 < n:
                    nxt = s[i+1]
                    if nxt in ('"', '\\'):
                        current_parts.append(nxt)
                    else:
                        current_parts.append('\\' + nxt)
                    i += 1
                else:
                    raise ValueError("Backslash at end of string")
            else:
                current_parts.append(c)
        else:
            if c == "'":
                in_single = True
                word_has_quotes = True
            elif c == '"':
                in_double = True
                word_has_quotes = True
            elif c in (' ', '\t', '\n', '\r'):
                if current_parts or word_has_quotes:
                    words.append(''.join(current_parts))
                    current_parts = []
                    word_has_quotes = False
                i += 1
                continue
            elif c == '\\':
                if i + 1 < n:
                    current_parts.append(s[i+1])
                    i += 1
                else:
                    raise ValueError("Backslash at end of string")
            else:
                current_parts.append(c)
        i += 1

    if in_single or in_double:
        raise ValueError("Unterminated quote")
    if current_parts or word_has_quotes:
        words.append(''.join(current_parts))

    return words

def parse_str_literal(src: str) -> str:
    if not src:
        raise ValueError("empty input")

    i = 0
    raw = False
    if src[0] in 'rR':
        raw = True
        i = 1
    if i >= len(src):
        raise ValueError("missing quote")

    quote_char = None
    quote_len = 0
    if src[i] in "'\"":
        quote_char = src[i]
        quote_len = 1
        i += 1
    elif src[i:i+3] in ("'''", '"""'):
        quote_char = src[i]
        quote_len = 3
        i += 3
    else:
        raise ValueError("unsupported prefix or invalid quote")

    res = []
    n = len(src)
    found_close = False

    while i < n:
        if src[i] == quote_char:
            if raw:
                # Count preceding backslashes to determine if quote is escaped
                backslash_count = 0
                j = i - 1
                while j >= 0 and src[j] == '\\':
                    backslash_count += 1
                    j -= 1
                if backslash_count % 2 == 1:
                    # Quote is escaped in raw string
                    res.append('\\' * backslash_count)
                    res.append(quote_char)
                    i += 1
                    continue
                else:
                    # Closing quote found
                    i += 1
                    found_close = True
                    break
            else:
                # In standard strings, sequential processing ensures we only see
                # unescaped quotes here. Escaped quotes were consumed by the backslash handler.
                i += 1
                found_close = True
                break

        if raw:
            res.append(src[i])
            i += 1
        else:
            if src[i] == '\\':
                j = i + 1
                if j >= n:
                    raise ValueError("unterminated escape sequence")
                c = src[j]

                if c == '\n':
                    # Line continuation: remove backslash and newline
                    i = j + 1
                    continue
                if c in '\\\'\"abfnrtv':
                    esc_map = {'\\':'\\', '\'':"'", '\"':'"', 'a':'\a', 'b':'\b', 'f':'\f', 'n':'\n', 'r':'\r', 't':'\t', 'v':'\v'}
                    res.append(esc_map[c])
                    i = j + 1
                    continue
                if c == 'x':
                    if j + 2 >= n or not all(src[k] in '0123456789abcdefABCDEF' for k in range(j+1, j+3)):
                        raise ValueError("malformed \\x escape")
                    res.append(chr(int(src[j+1:j+3], 16)))
                    i = j + 3
                    continue
                if c == 'u':
                    if j + 4 >= n or not all(src[k] in '0123456789abcdefABCDEF' for k in range(j+1, j+5)):
                        raise ValueError("malformed \\u escape")
                    res.append(chr(int(src[j+1:j+5], 16)))
                    i = j + 5
                    continue
                if c == 'U':
                    if j + 8 >= n or not all(src[k] in '0123456789abcdefABCDEF' for k in range(j+1, j+9)):
                        raise ValueError("malformed \\U escape")
                    val = int(src[j+1:j+9], 16)
                    if val > 0x10FFFF:
                        raise ValueError("U escape value exceeds 0x10FFFF")
                    res.append(chr(val))
                    i = j + 9
                    continue
                if c in '01234567':
                    digits = c
                    for _ in range(2):
                        if j + len(digits) < n and src[j + len(digits)] in '01234567':
                            digits += src[j + len(digits)]
                        else:
                            break
                    res.append(chr(int(digits, 8)))
                    i = j + len(digits)
                    continue
                # Fallback: backslash followed by unrecognized character
                res.append('\\')
                res.append(c)
                i = j + 1
            else:
