def parse_str_literal(src: str) -> str:
    n = len(src)
    if n == 0:
        raise ValueError("missing literal")

    pos = 0
    raw = False
    if src[0] in 'rR':
        raw = True
        pos = 1

    if pos >= n:
        raise ValueError("missing quote")

    quote = None
    quote_len = 0
    if src[pos:pos+3] in ("'''", '"""'):
        quote = src[pos:pos+3]
        quote_len = 3
        pos += 3
    elif src[pos] in ("'", '"'):
        quote = src[pos]
        quote_len = 1
        pos += 1
    else:
        raise ValueError("unsupported prefix or missing quote")

    res = []
    while pos < n:
        if src[pos] == '\\' and not raw:
            pos += 1
            if pos >= n:
                raise ValueError("unterminated literal")
            c = src[pos]

            if c == '\n':
                # Line continuation: remove backslash and newline
                pos += 1
            elif c == '\\':
                res.append('\\')
                pos += 1
            elif c == "'":
                res.append("'")
                pos += 1
            elif c == '"':
                res.append('"')
                pos += 1
            elif c == 'a':
                res.append('\a')
                pos += 1
            elif c == 'b':
                res.append('\b')
                pos += 1
            elif c == 'f':
                res.append('\f')
                pos += 1
            elif c == 'r':
                res.append('\r')
                pos += 1
            elif c == 't':
                res.append('\t')
                pos += 1
            elif c == 'v':
                res.append('\v')
                pos += 1
            elif c == 'x':
                pos += 1
                if pos + 2 > n or not all(ch in '0123456789abcdefABCDEF' for ch in src[pos:pos+2]):
                    raise ValueError("malformed \\x escape")
                res.append(chr(int(src[pos:pos+2], 16)))
                pos += 2
            elif c == 'u':
                pos += 1
                if pos + 4 > n or not all(ch in '0123456789abcdefABCDEF' for ch in src[pos:pos+4]):
                    raise ValueError("malformed \\u escape")
                res.append(chr(int(src[pos:pos+4], 16)))
                pos += 4
            elif c == 'U':
                pos += 1
                if pos + 8 > n or not all(ch in '0123456789abcdefABCDEF' for ch in src[pos:pos+8]):
                    raise ValueError("malformed \\U escape")
                val = int(src[pos:pos+8], 16)
                if val > 0x10FFFF:
                    raise ValueError("value above 0x10FFFF")
                res.append(chr(val))
                pos += 8
            elif c in '01234567':
                digits = []
                while pos < n and src[pos] in '01234567' and len(digits) < 3:
                    digits.append(src[pos])
                    pos += 1
                res.append(chr(int(''.join(digits), 8)))
            else:
                # Unknown escape: keep backslash and character
                res.append('\\')
                res.append(c)
                pos += 1
        elif src[pos] == '\\' and raw:
            res.append('\\')
            pos += 1
            if pos < n:
                res.append(src[pos])
                pos += 1
            else:
                # Raw string ends with a backslash without closing quote
                raise ValueError("unterminated raw string")
        else:
            if src[pos:pos+quote_len] == quote:
                pos += quote_len
                break
            if quote_len == 1 and src[pos] == '\n':
                raise ValueError("raw newline in single-quoted string")
            res.append(src[pos])
            pos += 1
    else:
        raise ValueError("unterminated literal")

    if pos != n:
        raise ValueError("anything after closing quote")

    return ''.join(res)

