from functools import lru_cache

def glob_match(pattern: str, path: str) -> bool:
    def match_segment(pat: str, path_seg: str) -> bool:
        # Tokenize the pattern segment
        tokens = []
        i = 0
        n = len(pat)
        while i < n:
            c = pat[i]
            if c == '\\':
                if i + 1 < n:
                    tokens.append(('LIT', pat[i+1]))
                    i += 2
                else:
                    tokens.append(('LIT', '\\'))
                    i += 1
            elif c == '*':
                tokens.append(('STAR',))
                i += 1
            elif c == '?':
                tokens.append(('QMARK',))
                i += 1
            elif c == '[':
                negated = False
                i += 1
                if i < n and pat[i] == '!':
                    negated = True
                    i += 1
                if i < n and pat[i] == ']':
                    tokens.append(('LIT', ']'))
                    i += 1
                    continue
                chars = set()
                while i < n and pat[i] != ']':
                    if i + 2 < n and pat[i+1] == '-' and pat[i+2] != ']':
                        start = pat[i]
                        end = pat[i+2]
                        for code in range(ord(start), ord(end) + 1):
                            chars.add(chr(code))
                        i += 3
                    else:
                        chars.add(pat[i])
                        i += 1
                if i < n:
                    i += 1  # skip closing ]
                tokens.append(('CLASS', chars, negated))
            else:
                tokens.append(('LIT', c))
                i += 1

        m = len(tokens)
        length_path = len(path_seg)
        # dp[j] corresponds to whether tokens[i:] matches path_seg[j:]
        dp = [False] * (length_path + 1)
        dp[length_path] = True

        for i in range(m - 1, -1, -1):
            new_dp = [False] * (length_path + 1)
            tok = tokens[i]
            for j in range(length_path, -1, -1):
                if tok[0] == 'STAR':
                    # STAR matches empty -> dp[j] (tokens[i+1:] vs path_seg[j:])
                    # STAR matches 1+ char -> new_dp[j+1] (tokens[i:] vs path_seg[j+1:])
                    new_dp[j] = dp[j] or (j < length_path and new_dp[j+1])
                elif tok[0] == 'QMARK':
                    if j < length_path:
                        new_dp[j] = dp[j+1]
                elif tok[0] == 'CLASS':
                    _, chars, negated = tok
                    if j < length_path:
                        if (path_seg[j] in chars) != negated:
                            new_dp[j] = dp[j+1]
                else:  # LIT
                    if j < length_path and path_seg[j] == tok[1]:
                        new_dp[j] = dp[j+1]
            dp = new_dp
        return dp[0]

    match_segment = lru_cache(maxsize=None)(match_segment)

    pat_segs = pattern.split('/')
    path_segs = path.split('/')

    P = len(pat_segs)
    Q = len(path_segs)

    # dp[j] corresponds to whether pat_segs[i:] matches path_segs[j:]
    dp = [False] * (Q + 1)
    dp[Q] = True

    for i in range(P - 1, -1, -1):
        new_dp = [False] * (Q + 1)
        seg = pat_segs[i]
        if seg == '**':
            # ** matches zero segments -> dp[j]
            # ** matches one or more segments -> new_dp[j+1]
            for j in range(Q, -1, -1):
                new_dp[j] = dp[j] or (j < Q and new_dp[j+1])
        else:
            for j in range(Q, -1, -1):
                if j < Q and match_segment(seg, path_segs[j]):
                    new_dp[j] = dp[j+1]
        dp = new_dp

    return dp[0]

def justify(text: str, width: int) -> list[str]:
    words = text.split()
    if not words:
        return []

    # Expand words longer than width into chunks of exactly width
    expanded = []
    for w in words:
        if len(w) > width:
            expanded.extend(w[i:i+width] for i in range(0, len(w), width))
        else:
            expanded.append(w)

    # Greedy line packing
    lines_words = []
    current_words = []
    current_len = 0
    for w in expanded:
        if not current_words:
            needed = len(w)
        else:
            needed = current_len + 1 + len(w)

        if needed > width:
            lines_words.append(current_words)
            current_words = [w]
            current_len = len(w)
        else:
            current_words.append(w)
            current_len = needed

    if current_words:
        lines_words.append(current_words)

    # Format lines according to rules
    result = []
    for i, line_w in enumerate(lines_words):
        is_last = (i == len(lines_words) - 1)
        if is_last:
            line_str = " ".join(line_w).ljust(width)
        elif len(line_w) == 1:
            line_str = line_w[0].ljust(width)
        else:
            total_chars = sum(len(w) for w in line_w)
            spaces_needed = width - total_chars
            num_gaps = len(line_w) - 1
            base_space = spaces_needed // num_gaps
            extra_spaces = spaces_needed % num_gaps

            parts = []
            for j, w in enumerate(line_w):
                parts.append(w)
                if j < len(line_w) - 1:
                    num_spaces = base_space + (1 if j < extra_spaces else 0)
                    parts.append(" " * num_spaces)
            line_str = "".join(parts)
        result.append(line_str)

    return result

import re

def apply_patch(old: list[str], patch: str) -> list[str]:
    if patch == '':
        return old.copy()

    lines = patch.split('\n')
    # Remove trailing empty lines resulting from a final newline
    while lines and lines[-1] == '':
        lines.pop()

    if len(lines) < 2 or not lines[0].startswith('--- ') or not lines[1].startswith('+++ '):
        raise ValueError("Invalid patch header")

    if len(lines) < 3:
        raise ValueError("No hunks found")

    hunk_idx = 2
    old_idx = 0
    new_lines = []
    expected_new_idx = 0
    prev_old_end = 0

    hunk_re = re.compile(r'^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@$')

    while hunk_idx < len(lines):
        line = lines[hunk_idx]
        m = hunk_re.match(line)
        if not m:
            raise ValueError("Malformed hunk header")

        S = int(m.group(1))
        C = int(m.group(2)) if m.group(2) is not None else 1
        S2 = int(m.group(3))
        C2 = int(m.group(4)) if m.group(4) is not None else 1

        if C < 0 or C2 < 0 or S < 0 or S2 < 0:
            raise ValueError("Invalid hunk header numbers")

        old_start = S - 1 if C > 0 else S
        new_start = S2 - 1 if C2 > 0 else S2

        if old_start != prev_old_end or old_start > len(old):
            raise ValueError("Hunk old start out of bounds or mismatch")
        if new_start != expected_new_idx:
            raise ValueError("Hunk new start mismatch")

        hunk_idx += 1
        c_rem = C
        c2_rem = C2

        while c_rem > 0 or c2_rem > 0:
            if hunk_idx >= len(lines):
                raise ValueError("Hunk body ended prematurely")

            body_line = lines[hunk_idx]
            if len(body_line) == 0:
                raise ValueError("Empty body line")

            kind = body_line[0]
            text = body_line[1:]

            if kind not in (' ', '-', '+'):
                raise ValueError("Invalid body line prefix")

            if kind in (' ', '-'):
                if c_rem == 0:
                    raise ValueError("Old side count exceeded")
                c_rem -= 1
                if old_idx >= len(old):
                    raise ValueError("Old side exhausted unexpectedly")
                if text != old[old_idx]:
                    raise ValueError("Context/Old line mismatch")
                old_idx += 1

            if kind in (' ', '+'):
                if c2_rem == 0:
                    raise ValueError("New side count exceeded")
                c2_rem -= 1
                new_lines.append(text)
                expected_new_idx += 1

            hunk_idx += 1

        if c_rem != 0 or c2_rem != 0:
            raise ValueError("Hunk body counts mismatch")

        prev_old_end = old_idx

    new_lines.extend(old[old_idx:])
    return new_lines

import re

def apply_patch(old: list[str], patch: str) -> list[str]:
    if patch == "":
        return old.copy()

    lines = patch.rstrip("\n").split("\n")
    if len(lines) < 3:
        raise ValueError("Patch must contain header and at least one hunk")
    if not lines[0].startswith("--- ") or not lines[1].startswith("+++ "):
        raise ValueError("Invalid header")

    hunk_re = re.compile(r"^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@$")

    pos = 0
    new_lines = []
    accumulated_diff = 0
    i = 2

    while i < len(lines):
        m = hunk_re.match(lines[i])
        if not m:
            raise ValueError("Invalid hunk header")

        S = int(m.group(1))
        C = int(m.group(2)) if m.group(2) is not None else 1
        S2 = int(m.group(3))
        C2 = int(m.group(4)) if m.group(4) is not None else 1

        old_start_0 = S - 1 if C > 0 else S
        new_start_0 = S2 - 1 if C2 > 0 else S2

        if old_start_0 != pos:
            raise ValueError("Hunk start mismatch")
        if old_start_0 + C > len(old):
            raise ValueError("Hunk extends beyond old")
        if new_start_0 != old_start_0 + accumulated_diff:
            raise ValueError("S2 consistency mismatch")

        # Copy any unchanged lines before this hunk
        if pos < old_start_0:
            new_lines.extend(old[pos:old_start_0])

        ctx_del = 0
        ctx_add = 0
        hunk_end = False
        i += 1
        while i < len(lines):
            bline = lines[i]
            if len(bline) == 0:
                raise ValueError("Empty body line")
            tag = bline[0]
            text = bline[1:]

            if tag == " ":
                ctx_del += 1
                ctx_add += 1
                if text != old[pos]:
                    raise ValueError("Context line mismatch")
                new_lines.append(text)
                pos += 1
            elif tag == "-":
                ctx_del += 1
                if text != old[pos]:
                    raise ValueError("Delete line mismatch")
                pos += 1
            elif tag == "+":
                ctx_add += 1
                new_lines.append(text)
            else:
                raise ValueError("Invalid body tag")

            if ctx_del > C or ctx_add > C2:
                raise ValueError("Body line count exceeded")

            if ctx_del == C and ctx_add == C2:
                hunk_end = True
                i += 1
                break

        if not hunk_end:
            raise ValueError("Hunk body incomplete")

        accumulated_diff += C2 - C

    new_lines.extend(old[pos:])
    return new_lines

def apply_patch(old: list[str], patch: str) -> list[str]:
    if not patch:
        return old.copy()

    lines = patch.split("\n")
    if lines and lines[-1] == "":
        lines.pop()

    if len(lines) < 2:
        raise ValueError("Patch too short")
    if not lines[0].startswith("--- ") or not lines[1].startswith("+++ "):
        raise ValueError("Invalid header")

    lines = lines[2:]

    current_old_idx = 0
    new_lines = []
    prev_cumulative_diff = 0

    i = 0
    n = len(lines)

    while i < n:
        line = lines[i]
        if not line.startswith("@@ ") or not line.endswith(" @@"):
            raise ValueError(f"Invalid hunk header: {line}")

        header = line[3:-2]
        parts = header.split()
        if len(parts) != 2:
            raise ValueError("Invalid hunk header format")

        old_part = parts[0]
        new_part = parts[1]

        if not old_part.startswith("-") or not new_part.startswith("+"):
            raise ValueError("Invalid hunk header ranges")

        try:
            old_range = old_part[1:].split(",")
            new_range = new_part[1:].split(",")
            S = int(old_range[0])
            C = int(old_range[1]) if len(old_range) > 1 else 1
            S2 = int(new_range[0])
            C2 = int(new_range[1]) if len(new_range) > 1 else 1
        except (ValueError, IndexError):
            raise ValueError("Invalid hunk header numbers")

        if C < 0 or C2 < 0:
            raise ValueError("Counts must be non-negative")
        if C > 0 and S < 1:
            raise ValueError("S must be >= 1 when C > 0")
        if C2 > 0 and S2 < 1:
            raise ValueError("S2 must be >= 1 when C2 > 0")

        old_start = S if C == 0 else S - 1
        new_start = S2 if C2 == 0 else S2 - 1

        if old_start != current_old_idx:
            raise ValueError(f"Hunk old start mismatch: expected {current_old_idx}, got {old_start}")
        if new_start != current_old_idx + prev_cumulative_diff:
            raise ValueError(f"Hunk new start mismatch: expected {current_old_idx + prev_cumulative_diff}, got {new_start}")

        old_count = 0
        new_count = 0
        while i < n and (old_count < C or new_count < C2):
            bline = lines[i]
            if bline.startswith("@@ "):
                break 
            if not bline or bline[0] not in (' ', '-', '+'):
                raise ValueError("Invalid body line")
            kind = bline[0]
            text = bline[1:]
            if kind == ' ':
                if old_count < C:
                    if current_old_idx >= len(old) or old[current_old_idx] != text:
                        raise ValueError("Context line mismatch")
                    old_count += 1
                    current_old_idx += 1
                if new_count < C2:
                    new_count += 1
                    new_lines.append(text)
            elif kind == '-':
                if old_count < C:
                    if current_old_idx >= len(old) or old[current_old_idx] != text:
                        raise ValueError("Remove line mismatch")
                    old_count += 1
                    current_old_idx += 1
                else:
                    raise ValueError("Too many '-' lines")
            elif kind == '+':
                if new_count < C2:
                    new_count += 1
                    new_lines.append(text)
                else:
                    raise ValueError("Too many '+' lines")
            i += 1

        if old_count != C or new_count != C2:
            raise ValueError("Hunk body line counts mismatch")

        prev_cumulative_diff += (C2 - C)

    if current_old_idx != len(old):
        raise ValueError("Hunk ended before end of old")

    return new_lines

