class _Parser:
    def __init__(self, s: str):
        self.s = s
        self.pos = 0
        self.n = len(s)

    def peek(self):
        if self.pos < self.n:
            return self.s[self.pos]
        return None

    def advance(self, n=1):
        self.pos += n

    def skip_ws(self):
        while self.pos < self.n and self.s[self.pos] in ' \t\n\r':
            self.pos += 1

    def expect(self, char):
        if self.pos >= self.n or self.s[self.pos] != char:
            raise ValueError(f"Expected '{char}'")
        self.advance()

    def read_name(self):
        if self.pos >= self.n:
            raise ValueError("Unexpected end of input")
        c = self.s[self.pos]
        if not (c.isalpha() or c == '_'):
            raise ValueError(f"Invalid name start: {c}")

        start = self.pos
        self.advance()
        while self.pos < self.n:
            c = self.s[self.pos]
            if not (c.isalnum() or c in '_.-'):
                break
            self.advance()
        return self.s[start:self.pos]

    def parse_attributes(self):
        attrs = {}
        while True:
            start_pos = self.pos
            self.skip_ws()

            # Check if we are at end of tag
            if self.peek() in ('>', '/'):
                break

            # If we didn't skip whitespace, and we are not at end of tag,
            # it means attributes are not separated by whitespace.
            if self.pos == start_pos:
                # If it looks like a name, it's a missing whitespace error.
                # Otherwise it's a syntax error handled elsewhere.
                if self.peek() and (self.peek().isalpha() or self.peek() == '_'):
                    raise ValueError("Attributes not separated by whitespace")

            # Parse attribute name
            name = self.read_name()

            self.skip_ws()
            self.expect('=')
            self.skip_ws()

            # Parse value
            value = self.parse_value()

            if name in attrs:
                raise ValueError(f"Duplicate attribute: {name}")
            attrs[name] = value

        return attrs

    def parse_value(self):
        quote = self.peek()
        if quote not in ('"', "'"):
            raise ValueError("Expected quote")
        self.advance()

        val_chars = []
        while self.pos < self.n:
            c = self.peek()
            if c == quote:
                self.advance()
                break
            if c == '<':
                raise ValueError("'<' not allowed in attribute value")
            if c == '&':
                char = self.parse_reference()
                val_chars.append(char)
            else:
                val_chars.append(c)
                self.advance()
        else:
            raise ValueError("Unterminated attribute value")

        return "".join(val_chars)

    def parse_reference(self):
        # self.s[self.pos] is '&'
        if self.pos + 1 >= self.n:
            raise ValueError("Unterminated reference")

        next_char = self.s[self.pos + 1]

        if next_char == '#':
            if self.pos + 2 >= self.n:
                raise ValueError("Unterminated reference")

            second = self.s[self.pos + 2]
            if second == 'x':
                # Hex
                start = self.pos + 3
                end = self.s.find(';', self.pos)
                if end == -1:
                    raise ValueError("Missing semicolon in reference")

                hex_str = self.s[start:end]
                if not hex_str:
                    raise ValueError("Empty hex digits")
                for h in hex_str:
                    if h not in '0123456789abcdefABCDEF':
                        raise ValueError("Invalid hex digit")

                code = int(hex_str, 16)
            elif second == 'X':
                raise ValueError("Hex reference must use lowercase x")
            else:
                # Decimal
                start = self.pos + 2
                end = self.s.find(';', self.pos)
                if end == -1:
                    raise ValueError("Missing semicolon in reference")

                dec_str = self.s[start:end]
                if not dec_str:
                    raise ValueError("Empty decimal digits")
                for d in dec_str:
                    if d not in '0123456789':
                        raise ValueError("Invalid decimal digit")

                code = int(dec_str)
            else:
                raise ValueError("Invalid reference format")

            # Validate code point
            if code < 1 or code > 0x10FFFF:
                raise ValueError(f"Invalid code point: {code}")
            if 0xD800 <= code <= 0xDFFF:
                raise ValueError("Surrogate code point")

            self.pos = end + 1
            return chr(code)

        else:
            # Named entity
            end = self.s.find(';', self.pos)
            if end == -1:
                raise ValueError("Missing semicolon in reference")

            entity = self.s[self.pos+1:end]
            self.pos = end + 1

            if entity == 'lt':
                return '<'
            elif entity == 'gt':
                return '>'
            elif entity == 'amp':
                return '&'
            elif entity == 'quot':
                return '"'
            elif entity == 'apos':
                return "'"
            else:
                raise ValueError(f"Unknown entity: &{entity};")

    def parse_content(self, expected_tag):
        children = []
        text_buf = []

        while self.pos < self.n:
            c = self.peek()

            if c == '<':
                # Check for end tag
                if self.s[self.pos:self.pos+2] == '</':
                    break

                # Child element
                text = "".join(text_buf)
                if text:
                    children.append(text)
                    text_buf = []

                child = self.parse_element()
                children.append(child)

            elif c == '&':
                char = self.parse_reference()
                text_buf.append(char)
            else:
                # Text
                start = self.pos
                while self.pos < self.n:
                    cc = self.s[self.pos]
                    if cc == '<' or cc == '&':
                        break
                    self.pos += 1
                if self.pos > start:
                    text_buf.append(self.s[start:self.pos])

        text = "".join(text_buf)
        if text:
            children.append(text)

        self.expect('</')
        tag_name = self.read_name()
        if tag_name != expected_tag:
            raise ValueError(f"Mismatched tags: expected {expected_tag}, got {tag_name}")

        self.skip_ws()
        self.expect('>')

        return children

    def parse_element(self):
        self.expect('<')
        tag = self.read_name()
        attrs = self.parse_attributes()

        self.skip_ws()

        if self.peek() == '/':
            self.expect('/>')
            return (tag, attrs, [])
        elif self.peek() == '>':
            self.expect('>')
            children = self.parse_content(tag)
            return (tag, attrs, children)
        else:
            raise ValueError("Invalid element syntax")

