                raise ValueError("Unterminated reference")

            second = self.s[self.pos + 2]
            if second == 'x':
                # Hex
                start = self.pos + 3
                end = self.s.find(';', self.pos)
                if end == -1:
                    raise ValueError("Missing semicolon in reference")

                hex_str = self.s[start:end]
                if not hex_str:
                    raise ValueError("Empty hex digits")
                for h in hex_str:
                    if h not in '0123456789abcdefABCDEF':
                        raise ValueError("Invalid hex digit")

                code = int(hex_str, 16)
            elif second == 'X':
                raise ValueError("Hex reference must use lowercase x")
            elif second.isdigit():
                # Decimal
                start = self.pos + 2
                end = self.s.find(';', self.pos)
                if end == -1:
                    raise ValueError("Missing semicolon in reference")

                dec_str = self.s[start:end]
                if not dec_str:
                    raise ValueError("Empty decimal digits")
                for d in dec_str:
                    if d not in '0123456789':
                        raise ValueError("Invalid decimal digit")

                code = int(dec_str)
            else:
                raise ValueError("Invalid reference format")

            # Validate code point
            if code < 1 or code > 0x10FFFF:
                raise ValueError(f"Invalid code point: {code}")
            if 0xD800 <= code <= 0xDFFF:
                raise ValueError("Surrogate code point")

            self.pos = end + 1
            return chr(code)

        else:
            # Named entity
            end = self.s.find(';', self.pos)
            if end == -1:
                raise ValueError("Missing semicolon in reference")

            entity = self.s[self.pos+1:end]
            self.pos = end + 1

            if entity == 'lt':
                return '<'
            elif entity == 'gt':
                return '>'
            elif entity == 'amp':
                return '&'
            elif entity == 'quot':
                return '"'
            elif entity == 'apos':
                return "'"
            else:
                raise ValueError(f"Unknown entity: &{entity};")

    def parse_content(self, expected_tag):
        children = []
        text_buf = []

        while self.pos < self.n:
            c = self.peek()

            if c == '<':
                # Check for end tag
                if self.s[self.pos:self.pos+2] == '</':
                    break

                # Child element
                text = "".join(text_buf)
                if text:
                    children.append(text)
                    text_buf = []

                child = self.parse_element()
                children.append(child)

            elif c == '&':
                char = self.parse_reference()
                text_buf.append(char)
            else:
                # Text
                start = self.pos
                while self.pos < self.n:
                    cc = self.s[self.pos]
                    if cc == '<' or cc == '&':
                        break
                    self.pos += 1
                if self.pos > start:
                    text_buf.append(self.s[start:self.pos])

        text = "".join(text_buf)
        if text:
            children.append(text)

        self.expect('<')
        self.expect('/')
        tag_name = self.read_name()
        if tag_name != expected_tag:
            raise ValueError(f"Mismatched tags: expected {expected_tag}, got {tag_name}")

        self.skip_ws()
        self.expect('>')

        return children

    def parse_element(self):
        self.expect('<')
        tag = self.read_name()
        attrs = self.parse_attributes()

        self.skip_ws()

        if self.peek() == '/':
            self.expect('/')
            self.expect('>')
            return (tag, attrs, [])
        elif self.peek() == '>':
            self.expect('>')
            children = self.parse_content(tag)
            return (tag, attrs, children)
        else:
            raise ValueError("Invalid element syntax")

def pal_partition(s: str) -> list[str]:
    n = len(s)
    if n == 0:
        return []

    # is_pal[i][j] will be True if s[i:j] is a palindrome
    is_pal = [[False] * (n + 1) for _ in range(n)]

    # Fill palindrome table
    for length in range(1, n + 1):
        for i in range(n - length + 1):
            j = i + length
            if s[i] == s[j-1] and (length <= 2 or is_pal[i+1][j-1]):
                is_pal[i][j] = True

    # dp[i] stores the minimum number of palindromic pieces for s[i:]
    dp = [n + 1] * (n + 1)
    dp[n] = 0
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n + 1):
            if is_pal[i][j] and dp[j] + 1 < dp[i]:
                dp[i] = dp[j] + 1

    # Reconstruct the partition according to the tie-breaking rule
    res = []
    curr = 0
    while curr < n:
        # Find the longest palindrome prefix s[curr:j] that allows the rest to be partitioned optimally
        for j in range(n, curr, -1):
            if is_pal[curr][j] and dp[j] == dp[curr] - 1:
                res.append(s[curr:j])
                curr = j
                break

    return res

def edit_script(a: str, b: str) -> list[str]:
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base cases
    for j in range(n + 1):
        dp[m][j] = n - j
    for i in range(m + 1):
        dp[i][n] = m - i

    # Fill DP table
    for i in range(m - 1, -1, -1):
        row = dp[i]
        row_next = dp[i + 1]
        for j in range(n - 1, -1, -1):
            if a[i] == b[j]:
                row[j] = row_next[j + 1]
            else:
                row[j] = row_next[j + 1] + 1
            # min of match/sub, delete, insert
            d = row_next[j] + 1
            ins = row[j + 1] + 1
            if d < row[j]:
                row[j] = d
            if ins < row[j]:
                row[j] = ins

    # Reconstruct canonical path
    script = []
    i, j = 0, 0
    while i < m or j < n:
        # Priority 1: "="
        if i < m and j < n and a[i] == b[j] and dp[i][j] == dp[i+1][j+1]:
            script.append(f"={a[i]}")
            i += 1
            j += 1
        # Priority 2: "~"
        elif i < m and j < n and dp[i][j] == dp[i+1][j+1] + 1:
            script.append(f"~{a[i]}{b[j]}")
            i += 1
            j += 1
        # Priority 3: "-"
        elif i < m and dp[i][j] == dp[i+1][j] + 1:
            script.append(f"-{a[i]}")
            i += 1
        # Priority 4: "+"
        elif j < n and dp[i][j] == dp[i][j+1] + 1:
            script.append(f"+{b[j]}")
            j += 1
        else:
            # Should not be reachable if DP is correct
            break
    return script

import math

def crt_solve(congruences: list[tuple[int, int]]) -> tuple[int, int] | None:
    for _, m in congruences:
        if m < 1:
            raise ValueError("Modulus must be >= 1")

    current_x = 0
    current_m = 1

    for a, m in congruences:
        if m == 1:
            continue

        g = math.gcd(current_m, m)
        rhs = a - current_x

        if rhs % g != 0:
            return None

        M = current_m // g
        N = m // g
        R = rhs // g

        if N == 1:
            k = 0
        else:
            inv_M = pow(M, -1, N)
            k = (R * inv_M) % N

        current_x = current_x + current_m * k
        current_m = current_m * N
        current_x %= current_m

    return current_x, current_m

def integer_root(n: int, p: int) -> tuple[int, bool]:
    """Returns (root, exact) such that root**p <= n < (root+1)**p."""
    if n < 0:
        if p % 2 == 0:
            return 0, False
        n = -n
    if n == 0:
        return 0, True
    if n == 1:
        return 1, True

    # Binary search for the integer p-th root
    low = 1
    # Upper bound: 2^(bit_length // p + 1) is guaranteed > n^(1/p)
    high = 1 << (n.bit_length() // p + 1)

    while low < high:
        mid = (low + high + 1) // 2
        if pow(mid, p) <= n:
            low = mid
        else:
            high = mid - 1

    return low, low**p == n


def perfect_power(n: int) -> tuple[int, int]:
    if abs(n) < 2:
        raise ValueError("abs(n) must be >= 2")

    M = abs(n)
    e = M.bit_length()

    # Try to reduce e by prime factors
    p = 2
    while p * p <= e:
        if e % p == 0:
            while e % p == 0:
                r, exact = integer_root(M, p)
                if exact:
                    e //= p
                    M = r
                else:
                    break
        p += 1

    if e > 1:
        r, exact = integer_root(M, e)
        if exact:
            M = r
            e = 1

    # For negative n, exponent must be odd
    if n < 0:
        while e % 2 == 0:
            e //= 2
        b, _ = integer_root(abs(n), e)
        return (-b, e)
    else:
        b, _ = integer_root(M, e)
        return (b, e)

def integer_root(n: int, p: int) -> tuple[int, bool]:
    """Returns (root, exact) such that root**p <= n < (root+1)**p."""
    if n < 0:
        if p % 2 == 0:
            return 0, False
        n = -n
    if n == 0:
        return 0, True
    if n == 1:
        return 1, True

    # Binary search for the integer p-th root
    # Lower bound is 1.
    # Upper bound: 2^(bit_length // p + 1) is guaranteed > n^(1/p)
    low = 1
    high = 1 << (n.bit_length() // p + 1)

    while low < high:
        mid = (low + high + 1) // 2
        if pow(mid, p) <= n:
            low = mid
        else:
            high = mid - 1

    return low, low**p == n


def perfect_power(n: int) -> tuple[int, int]:
    if abs(n) < 2:
        raise ValueError("abs(n) must be >= 2")

    # Handle negative numbers
    neg = False
    val = n
    if n < 0:
        val = -n
        neg = True

    # Find the maximal exponent E such that val = base^E
    # We iterate through prime factors of the exponent.
    # If val is a perfect p-th power, we divide the exponent by p (accumulate)
    # and take the p-th root of val. We repeat for the same p.

    e = 1
    p = 2

    # We only need to check p up to bit_length of val.
    # Actually, if 2^p > val, then val cannot be a perfect p-th power (since base >= 2).
    # So we can stop when 2^p > val.

    while True:
        # Check if 2^p > val. If so, no perfect p-th power exists for p (base >= 2).
        # We can compute 2^p efficiently or check bit length.
        # 2^p has bit length p+1.
        # If p+1 > val.bit_length(), then 2^p > val.
        if p + 1 > val.bit_length():
            break

        root, exact = integer_root(val, p)
        if exact:
            val = root
            e *= p
            # Do not increment p, check same p again on the new smaller val
            continue
        else:
            p += 1

    # For negative n, the exponent must be odd.
    # If we found an even exponent, we must reduce it to the largest odd divisor.
    if neg:
        while e % 2 == 0:
            e //= 2
        # The base must be negative.
        # We had val^e = |n|. Now we want b^e = n = -|n|.
        # So b = -val.
        return (-val, e)
    else:
        return (val, e)

def convex_hull(points: list[tuple[int, int]]) -> list[tuple[int, int]]:
    pts = sorted(set(points))
    n = len(pts)
    if n == 0:
        return []
    if n == 1:
        return pts

    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    lower = []
    for p in pts:
        while len(lower) >= 2 and cross(lower[-2], lower[-1], p) <= 0:
            lower.pop()
        lower.append(p)

    upper = []
    for p in reversed(pts):
        while len(upper) >= 2 and cross(upper[-2], upper[-1], p) <= 0:
            upper.pop()
        upper.append(p)

    hull = lower[:-1] + upper[:-1]

    # Rotate to start at the point with smallest y (ties broken by smallest x)
    start = min(pts, key=lambda p: (p[1], p[0]))
    idx = hull.index(start)
    return hull[idx:] + hull[:idx]

def is_leap(y: int) -> bool:
    return (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)

def days_in_month(y: int, m: int) -> int:
    if m in (1, 3, 5, 7, 8, 10, 12):
        return 31
    if m in (4, 6, 9, 11):
        return 30
    return 29 if is_leap(y) else 28

def days_in_year(y: int) -> int:
    return 366 if is_leap(y) else 365

def day_of_year(y: int, m: int, d: int) -> int:
    doy = d
    for i in range(1, m):
        doy += days_in_month(y, i)
    return doy

def weekday_from_monday(y: int, m: int, d: int) -> int:
    total = (y - 1) * 365 + (y - 1) // 4 - (y - 1) // 100 + (y - 1) // 400
    total += day_of_year(y, m, d)
    return (total - 1) % 7 + 1

def validate_date(y: int, m: int, d: int) -> None:
    if not (1 <= y <= 9999):
        raise ValueError("Year out of range")
    if not (1 <= m <= 12):
        raise ValueError("Month out of range")
    if not (1 <= d <= days_in_month(y, m)):
        raise ValueError("Day out of range")

def doy_to_ymd(y: int, doy: int) -> tuple[int, int, int]:
    m = 1
    while m <= 12:
        dim = days_in_month(y, m)
        if doy <= dim:
            return y, m, doy
        doy -= dim
        m += 1
    raise ValueError("Invalid day of year")

def iso_weeks_in_year(y: int) -> int:
    w_jan1 = weekday_from_monday(y, 1, 1)
    if (w_jan1 == 4) or (w_jan1 == 3 and is_leap(y)):
        return 53
    return 52

def to_iso_week(year: int, month: int, day: int) -> tuple[int, int, int]:
    validate_date(year, month, day)

    w = weekday_from_monday(year, month, day)
    doy = day_of_year(year, month, day)
    days_in_y = days_in_year(year)

    days_to_mon = (w - 1) % 7
    mon_doy = doy - days_to_mon
    iso_year = year

    if mon_doy < 1:
        mon_doy += days_in_year(year - 1)
        iso_year -= 1
    elif mon_doy > days_in_y:
        mon_doy -= days_in_y
        iso_year += 1

    w_jan4 = weekday_from_monday(iso_year, 1, 4)
    days_to_mon_w1 = (w_jan4 - 1) % 7
    mon_w1_doy = 4 - days_to_mon_w1

    iso_week = (mon_doy - mon_w1_doy) // 7 + 1
    return iso_year, iso_week, w

def from_iso_week(iso_year: int, week: int, weekday: int) -> tuple[int, int, int]:
    if not (1 <= iso_year <= 9999):
        raise ValueError("ISO year out of range")
    if not (1 <= weekday <= 7):
        raise ValueError("Weekday out of range")
    if not (1 <= week <= iso_weeks_in_year(iso_year)):
        raise ValueError("Week out of range")

    w_jan4 = weekday_from_monday(iso_year, 1, 4)
    days_to_mon_w1 = (w_jan4 - 1) % 7
    mon_w1_doy = 4 - days_to_mon_w1

    if mon_w1_doy < 1:
        base_year = iso_year - 1
        base_doy = mon_w1_doy + days_in_year(base_year)
    else:
        base_year = iso_year
        base_doy = mon_w1_doy

    target_doy = base_doy + (week - 1) * 7 + (weekday - 1)

    y = base_year
    while target_doy > days_in_year(y):
        target_doy -= days_in_year(y)
        y += 1

    if y < 1 or y > 9999:
        raise ValueError("Resulting date out of range")

    return doy_to_ymd(y, target_doy)

def _is_leap(y: int) -> bool:
    return (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)


def _days_in_month(y: int, m: int) -> int:
    _DAYS = (0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)
    if m == 2 and _is_leap(y):
        return 29
    return _DAYS[m]


def _days_before_year(y: int) -> int:
    # Days from 0001-01-01 to y-01-01
    return 365 * (y - 1) + (y - 1) // 4 - (y - 1) // 100 + (y - 1) // 400


def _days_before_month(y: int, m: int) -> int:
    return sum(_days_in_month(y, i) for i in range(1, m))


def _date_to_days(y: int, m: int, d: int) -> int:
    return _days_before_year(y) + _days_before_month(y, m) + (d - 1)


def _days_to_date(n: int) -> tuple[int, int, int]:
    # n is 0-based days from 0001-01-01
    cycles, rem = divmod(n, 146097)
    y = cycles * 400
    years, rem = divmod(rem, 365)
    if years == 4:
        years = 3
        rem += 365
    y += years
    m = 1
    while rem >= _days_in_month(y, m):
        rem -= _days_in_month(y, m)
        m += 1
    d = rem + 1
    return y, m, d


def _day_of_week(y: int, m: int, d: int) -> int:
    # 1=Monday, ..., 7=Sunday
    return _date_to_days(y, m, d) % 7 + 1


def _weeks_in_year(y: int) -> int:
    dow_dec31 = _day_of_week(y, 12, 31)
    doy_dec31 = 366 if _is_leap(y) else 365
    return (doy_dec31 - dow_dec31 + 10) // 7


def _validate_date(y: int, m: int, d: int) -> None:
    if not (1 <= y <= 9999):
        raise ValueError(f"Year must be between 1 and 9999, got {y}")
    if not (1 <= m <= 12):
        raise ValueError(f"Month must be between 1 and 12, got {m}")
    if not (1 <= d <= _days_in_month(y, m)):
        raise ValueError(f"Invalid day {d} for month {m}/{y}")


def to_iso_week(year: int, month: int, day: int) -> tuple[int, int, int]:
    _validate_date(year, month, day)

    dow = _day_of_week(year, month, day)
    doy = _date_to_days(year, month, day) - _date_to_days(year, 1, 1) + 1

    w = (doy - dow + 10) // 7

    if w == 0:
        iso_year = year - 1
        w = _weeks_in_year(iso_year)
    elif w == 53:
        if _weeks_in_year(year) != 53:
            iso_year = year + 1
            w = 1
        else:
            iso_year = year
    else:
        iso_year = year

    return iso_year, w, dow


def from_iso_week(iso_year: int, week: int, weekday: int) -> tuple[int, int, int]:
    if not (1 <= iso_year <= 9999):
        raise ValueError(f"ISO year must be between 1 and 9999, got {iso_year}")
    if not (1 <= weekday <= 7):
        raise ValueError(f"Weekday must be between 1 and 7, got {weekday}")
    if not (1 <= week <= _weeks_in_year(iso_year)):
        raise ValueError(f"Week must be between 1 and {_weeks_in_year(iso_year)}, got {week}")

    abs_jan4 = _date_to_days(iso_year, 1, 4)
    dow_jan4 = abs_jan4 % 7 + 1

    # Monday of week 1
    abs_mon_w1 = abs_jan4 - (dow_jan4 - 1)
    # Monday of target week
    abs_mon_w = abs_mon_w1 + (week - 1) * 7
    # Target day
    abs_target = abs_mon_w + (weekday - 1)

    y, m, d = _days_to_date(abs_target)

    if not (1 <= y <= 9999):
        raise ValueError(f"Resulting date year {y} is outside 1..9999")

    return y, m, d

def add_business_days(start: str, n: int, holidays: list[str]) -> str:
    def is_valid(s: str) -> bool:
        if len(s) != 10 or s[4] != '-' or s[7] != '-':
            return False
        return s[:4].isdigit() and s[5:7].isdigit() and s[8:].isdigit()

    def parse(s: str):
        if not is_valid(s):
            raise ValueError("Invalid date format")
        y, m, d = int(s[:4]), int(s[5:7]), int(s[8:])
        if not (1 <= m <= 12):
            raise ValueError("Invalid month")
        if m == 2:
            leap = (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)
            if not (1 <= d <= (29 if leap else 28)):
                raise ValueError("Invalid day")
        elif m in (4, 6, 9, 11):
            if not (1 <= d <= 30):
                raise ValueError("Invalid day")
        else:
            if not (1 <= d <= 31):
                raise ValueError("Invalid day")
        return y, m, d

    def is_leap(y: int) -> bool:
        return (y % 4 == 0 and y % 100 != 0) or (y % 400 == 0)

    def days_in_month(y: int, m: int) -> int:
        if m == 2 and is_leap(y):
            return 29
        return (0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31)[m]

    def add_days(y: int, m: int, d: int, delta: int):
        if delta >= 0:
            for _ in range(delta):
                d += 1
                if d > days_in_month(y, m):
                    d = 1
                    m += 1
                    if m > 12:
                        m = 1
                        y += 1
        else:
            for _ in range(-delta):
                d -= 1
                if d < 1:
                    m -= 1
                    if m < 1:
                        m = 12
                        y -= 1
                    d = days_in_month(y, m)
        return y, m, d

    def day_of_week(y: int, m: int, d: int) -> int:
        # Returns 0=Monday, 1=Tuesday, ..., 6=Sunday
        t = [0, 3, 2, 5, 0, 3, 5, 1, 4, 6, 2, 4]
        yy = y - 1 if m < 3 else y
        w = (yy + yy // 4 - yy // 100 + yy // 400 + t[m - 1] + d) % 7
        return (w + 6) % 7

    sy, sm, sd = parse(start)
    closed_days = set()
    for h in holidays:
        hy, hm, hd = parse(h)
        closed_days.add((hy, hm, hd))
        dow = day_of_week(hy, hm, hd)
        if dow == 5:  # Saturday -> observed Friday
            oy, om, od = add_days(hy, hm, hd, -1)
            closed_days.add((oy, om, od))
        elif dow == 6:  # Sunday -> observed Monday
            oy, om, od = add_days(hy, hm, hd, 1)
            closed_days.add((oy, om, od))

    def is_business_day(y: int, m: int, d: int) -> bool:
        return 0 <= day_of_week(y, m, d) <= 4 and (y, m, d) not in closed_days

    curr = (sy, sm, sd)

    if n > 0:
        count = 0
        while count < n:
            curr = add_days(curr[0], curr[1], curr[2], 1)
            if is_business_day(*curr):
                count += 1
    elif n < 0:
        count = 0
        while count < abs(n):
            curr = add_days(curr[0], curr[1], curr[2], -1)
            if is_business_day(*curr):
                count += 1
    else:  # n == 0
        if not is_business_day(*curr):
            curr = add_days(curr[0], curr[1], curr[2], 1)
            while not is_business_day(*curr):
                curr = add_days(curr[0], curr[1], curr[2], 1)

    return f"{curr[0]:04d}-{curr[1]:02d}-{curr[2]:02d}"

def gf_solve(A: list[list[int]], b: list[int], p: int):
    # Input Validation
    if not A:
        raise ValueError("A is empty")

    m = len(A)
    n = -1

    for row in A:
        if not row:
            raise ValueError("Row is empty")
        if n == -1:
            n = len(row)
        elif len(row) != n:
            raise ValueError("Rows have different lengths")

    if len(b) != m:
        raise ValueError("len(b) != m")
    if p < 2:
        raise ValueError("p < 2")

    # Preprocessing: Reduce modulo p and form augmented matrix
    # M will be m x (n + 1)
    M = []
    for i in range(m):
        row = []
        for j in range(n):
            row.append(A[i][j] % p)
        row.append(b[i] % p)
        M.append(row)

    # Gaussian Elimination to Reduced Row Echelon Form (RREF)
    pivot_cols = []
    pivot_rows_map = {}  # Maps pivot column index to pivot row index

    current_row = 0
    for col in range(n):
        if current_row >= m:
            break

        # Find a pivot in the current column, starting from current_row
        pivot_row = -1
        for r in range(current_row, m):
            if M[r][col] != 0:
                pivot_row = r
                break

        if pivot_row == -1:
            # No pivot found in this column; it is a free column
            continue

        # Swap the current row with the pivot row
        M[current_row], M[pivot_row] = M[pivot_row], M[current_row]

        # Normalize the pivot row so that the pivot element is 1
        pivot_val = M[current_row][col]
        inv = pow(pivot_val, p - 2, p)  # Modular inverse using Fermat's Little Theorem

        pivot_row_ref = M[current_row]
        for k in range(n + 1):
            pivot_row_ref[k] = (pivot_row_ref[k] * inv) % p

        # Eliminate all other entries in the pivot column (Gauss-Jordan step)
        for r in range(m):
            if r != current_row:
                factor = M[r][col]
                if factor != 0:
                    row_r = M[r]
                    # row_r = row_r - factor * pivot_row_ref
                    for k in range(n + 1):
                        row_r[k] = (row_r[k] - factor * pivot_row_ref[k]) % p

        # Record the pivot
        pivot_cols.append(col)
        pivot_rows_map[col] = current_row
        current_row += 1

    # Check for inconsistency
    # Any row below the last pivot row (current_row to m-1) must be all zeros in the A part
    # If the augmented part is non-zero, the system is inconsistent (0 = non-zero)
    for r in range(current_row, m):
        if M[r][n] != 0:
            return None

    # Construct the solution vector x
    # x[j] is 0 for free columns, and for pivot columns, x[col] = M[pivot_row][n]
    x = [0] * n
    for col, row in pivot_rows_map.items():
        x[col] = M[row][n] % p

    # Calculate dimension of solution space (nullity)
    # d = n - rank(A)
    rank = len(pivot_cols)
    d = n - rank

    return (x, d)

def best_rational(num: int, den: int, max_den: int) -> tuple[int, int]:
    if den == 0 or max_den < 1:
        raise ValueError("den must be non-zero and max_den must be >= 1")

    # Handle sign: we work with absolute value, restore sign to p at the end
    neg = (num < 0) != (den < 0)
    num, den = abs(num), abs(den)
    x_num, x_den = num, den

    # Stern-Brocot search for best rational approximation with q <= max_den
    # L = (pL, qL) represents left bound, R = (pR, qR) represents right bound
    # Initially bracket x: L = 0/1, R = 1/0 (infinity)
    # We maintain that L < x < R (or one equals x)
    pL, qL = 0, 1
    pR, qR = 1, 0

    while True:
        # Next mediant
        pM, qM = pL + pR, qL + qR
        if qM > max_den:
            break
        # Compare mediant with x: pM/qM < x  <=>  pM * x_den < x_num * qM
        if pM * x_den < x_num * qM:
            pL, qL = pM, qM
        else:
            pR, qR = pM, qM

    # Candidates are L and R
    # Compare |x - L| vs |x - R|
    # |x - p/q| = |x_num/q_den * q - p| / (q * q_den)
    # We compare numerators of differences scaled by common denominator qL*qR*x_den
    diffL = abs(x_num * qL - x_den * pL) * qR
    diffR = abs(x_num * qR - x_den * pR) * qL

    if diffL < diffR:
        p, q = pL, qL
    elif diffR < diffL:
        p, q = pR, qR
    else:
        # Tie in distance: prefer smaller q, then smaller value p/q
        if qL < qR:
            p, q = pL, qL
        elif qR < qL:
            p, q = pR, qR
        else:
            # Same q, prefer smaller p/q (i.e., smaller p since q>0)
            if pL < pR:
                p, q = pL, qL
            else:
                p, q = pR, qR

    # Apply sign
    if neg:
        p = -p
    # Reduce to lowest terms
    g = _gcd(p, q)
    p //= g
    q //= g
    return (p, q)


def _gcd(a: int, b: int) -> int:
    a, b = abs(a), abs(b)
    while b:
        a, b = b, a % b
    return a
